import sys
import bisect

def can_achieve_average(n, k, m, a, target_avg):
    operations_needed = 0
    for power in a:
        if power < target_avg:
            diff = target_avg - power
            if diff > k:
                return False
            operations_needed += diff
        else:
            operations_needed += max(0, power - target_avg)

    return operations_needed <= m

